using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;

namespace HslControls.Advanced
{
	public class HslChinaMap : NoBoundaryControl
	{
		private List<HslPathFigure> hslFigures;

		private bool showRiversAndLakes = true;

		private bool showCities = true;

		private List<HslCity> hslCities;

		private Color provinceColor = Color.Lavender;

		private Color provinceMoveColor = Color.LightSkyBlue;

		private bool canMouseMoveHighlight = true;

		private Pen dashPen = null;

		[Description("获取或设置是否显示河流及湖泊")]
		[DefaultValue(true)]
		[Category("HslControls")]
		public bool ShowRiversAndLakes
		{
			get
			{
				return showRiversAndLakes;
			}
			set
			{
				showRiversAndLakes = value;
				Invalidate();
			}
		}

		[Description("获取或设置是否城市的信息")]
		[DefaultValue(true)]
		[Category("HslControls")]
		public bool ShowCities
		{
			get
			{
				return showCities;
			}
			set
			{
				showCities = value;
				Invalidate();
			}
		}

		[Description("获取或设置鼠标移动到省时进行背景高亮显示")]
		[DefaultValue(true)]
		[Category("HslControls")]
		public bool CanMouseMoveHighlight
		{
			get
			{
				return canMouseMoveHighlight;
			}
			set
			{
				canMouseMoveHighlight = value;
				for (int i = 0; i < hslFigures.Count; i++)
				{
					hslFigures[i].Selected = false;
				}
				Invalidate();
			}
		}

		[Description("获取或设置全部省份的背景颜色信息")]
		[DefaultValue(typeof(Color), "Lavender")]
		[Category("HslControls")]
		public Color ProvinceColor
		{
			get
			{
				return provinceColor;
			}
			set
			{
				provinceColor = value;
				for (int i = 0; i < hslFigures.Count; i++)
				{
					hslFigures[i].FigureBackBrush?.Dispose();
					hslFigures[i].FigureBackBrush = new SolidBrush(value);
				}
				Invalidate();
			}
		}

		[Description("获取或设置省份的移动背景颜色信息")]
		[DefaultValue(typeof(Color), "LightSkyBlue")]
		[Category("HslControls")]
		public Color ProvinceMoveColor
		{
			get
			{
				return provinceMoveColor;
			}
			set
			{
				provinceMoveColor = value;
				for (int i = 0; i < hslFigures.Count; i++)
				{
					hslFigures[i].FigureSelectdBrush?.Dispose();
					hslFigures[i].FigureSelectdBrush = new SolidBrush(value);
				}
				Invalidate();
			}
		}

		public HslChinaMap()
		{
			hslFigures = new List<HslPathFigure>();
			MapInitialize();
		}

		protected override void OnLoad(EventArgs e)
		{
			base.OnLoad(e);
			base.Paint += HslChinaMap_Paint;
		}

		protected override void OnMouseLeave(EventArgs e)
		{
			base.OnMouseLeave(e);
			Invalidate();
		}

		protected override void OnMouseMove(MouseEventArgs e)
		{
			base.OnMouseMove(e);
			Point point = ControlToActualPoint(e.Location);
			if (canMouseMoveHighlight)
			{
				bool flag = false;
				for (int i = 0; i < hslFigures.Count; i++)
				{
					if (hslFigures[i].IsMouseIn(point))
					{
						hslFigures.ForEach(delegate(HslPathFigure m)
						{
							m.Selected = false;
						});
						hslFigures[i].Selected = true;
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					hslFigures.ForEach(delegate(HslPathFigure m)
					{
						m.Selected = false;
					});
				}
			}
			Invalidate();
		}

		protected override void OnMouseUp(MouseEventArgs e)
		{
			base.OnMouseUp(e);
			Invalidate();
		}

		protected override void OnMouseDown(MouseEventArgs e)
		{
			base.OnMouseDown(e);
			Invalidate();
		}

		private void HslChinaMap_Paint(object sender, PaintEventArgs e)
		{
			Graphics graphics = e.Graphics;
			Font font = new Font(Font.FontFamily, Font.Size / GetScales());
			Pen pen = new Pen(ForeColor, 1f / GetScales());
			Brush brush = new SolidBrush(ForeColor);
			for (int i = 0; i < hslFigures.Count; i++)
			{
				hslFigures[i].DrawCadFigure(graphics, Color.Tomato, Color.WhiteSmoke, Font, GetScales());
			}
			graphics.FillPolygon(Brushes.Tomato, new Point[11]
			{
				new Point(1053, 479),
				new Point(1057, 482),
				new Point(1056, 487),
				new Point(1060, 484),
				new Point(1064, 487),
				new Point(1063, 482),
				new Point(1067, 479),
				new Point(1062, 479),
				new Point(1060, 474),
				new Point(1058, 479),
				new Point(1053, 479)
			});
			if (showRiversAndLakes)
			{
				DrawRiversLakes(graphics);
			}
			DrawCitiesMark(graphics, font, pen, brush);
			if (showCities)
			{
				DrawCities(graphics, font, pen, brush);
			}
			graphics.DrawLine(pen, 1265, 1016, 1247, 1048);
			graphics.DrawLine(pen, 1194, 1159, 1179, 1192);
			graphics.DrawLine(pen, 1166, 1279, 1168, 1239);
			graphics.DrawLine(pen, 1149, 1414, 1159, 1375);
			graphics.DrawLine(pen, 1075, 1517, 1094, 1484);
			graphics.DrawLine(pen, 969, 1629, 1014, 1614);
			graphics.DrawLine(pen, 847, 1472, 851, 1502);
			graphics.DrawLine(pen, 920, 1291, 912, 1323);
			graphics.DrawLine(pen, 900, 1177, 913, 1203);
			font.Dispose();
			pen.Dispose();
			brush.Dispose();
		}

