		private void DrawCitiesMark(Graphics g, Font font, Pen pen, Brush fontBrush)
		{
			for (int i = 0; i < hslCities.Count; i++)
			{
				if (hslCities[i].MarkSize > 0 && hslCities[i].MarkBrush != null)
				{
					g.FillEllipse(hslCities[i].MarkBrush, hslCities[i].Location.X - hslCities[i].MarkSize, hslCities[i].Location.Y - hslCities[i].MarkSize, hslCities[i].MarkSize * 2, hslCities[i].MarkSize * 2);
				}
			}
		}

		private void DrawCities(Graphics g, Font font, Pen pen, Brush fontBrush)
		{
			if ((double)GetScales() < 0.4)
			{
				return;
			}
			for (int i = 0; i < hslCities.Count; i++)
			{
				PointF point = new PointF((float)hslCities[i].Location.X + (float)hslCities[i].Size / GetScales(), (float)hslCities[i].Location.Y + (float)hslCities[i].Size / GetScales());
				if (hslCities[i].ShowLocation == 1)
				{
					point = new PointF((float)hslCities[i].Location.X + (float)hslCities[i].Size / GetScales(), (float)(hslCities[i].Location.Y - font.Height) - (float)hslCities[i].Size / GetScales());
				}
				if (hslCities[i].Degree == 1)
				{
					if (hslCities[i].MarkSize <= 0)
					{
						g.FillEllipse(fontBrush, (float)hslCities[i].Location.X - (float)hslCities[i].Size / GetScales(), (float)hslCities[i].Location.Y - (float)hslCities[i].Size / GetScales(), (float)hslCities[i].Size / GetScales() * 2f, (float)hslCities[i].Size / GetScales() * 2f);
						g.DrawEllipse(pen, (float)hslCities[i].Location.X - (float)hslCities[i].Size / GetScales() - 2f / GetScales(), (float)hslCities[i].Location.Y - (float)hslCities[i].Size / GetScales() - 2f / GetScales(), (float)hslCities[i].Size / GetScales() * 2f + 4f / GetScales(), (float)hslCities[i].Size / GetScales() * 2f + 4f / GetScales());
					}
					if (GetScales() > 0.6f)
					{
						g.DrawString(hslCities[i].Name, font, fontBrush, point);
					}
				}
				else if (hslCities[i].Degree == 2)
				{
					if (GetScales() > 2f)
					{
						if (hslCities[i].MarkSize <= 0)
						{
							g.DrawEllipse(pen, (float)hslCities[i].Location.X - (float)hslCities[i].Size / GetScales(), (float)hslCities[i].Location.Y - (float)hslCities[i].Size / GetScales(), (float)hslCities[i].Size / GetScales() * 2f, (float)hslCities[i].Size / GetScales() * 2f);
						}
						g.DrawString(hslCities[i].Name, font, fontBrush, point);
					}
				}
				else if (hslCities[i].Degree != 3)
				{
					g.DrawString(hslCities[i].Name, font, fontBrush, point);
				}
			}
		}

		public void SetProvinceBackColor(string name, Color color)
		{
			for (int i = 0; i < hslFigures.Count; i++)
			{
				if (name.Contains(hslFigures[i].Name))
				{
					hslFigures[i].FigureBackBrush?.Dispose();
					hslFigures[i].FigureBackBrush = new SolidBrush(color);
					break;
				}
			}
			Invalidate();
		}

		public void MarkCity(string[] city, int[] markSize, Color[] markColor)
		{
			if (city == null || markSize == null || markColor == null)
			{
				throw new Exception("Parameter can not be NULL");
			}
			if (city.Length != markSize.Length || city.Length != markColor.Length)
			{
				throw new Exception("Array Size Must be same");
			}
			for (int i = 0; i < hslCities.Count; i++)
			{
				for (int j = 0; j < city.Length; j++)
				{
					if (hslCities[i].Name.Contains(city[j]))
					{
						hslCities[i].MarkSize = markSize[j];
						hslCities[i].MarkBrush?.Dispose();
						hslCities[i].MarkBrush = new SolidBrush(markColor[j]);
						break;
					}
				}
			}
			Invalidate();
		}

		public void MarkCityClear()
		{
			for (int i = 0; i < hslCities.Count; i++)
			{
				hslCities[i].MarkSize = -1;
			}
			Invalidate();
		}

		public void MarkRandomTest()
		{
			Random random = new Random();
			for (int i = 0; i < hslCities.Count; i++)
			{
				hslCities[i].MarkSize = random.Next(8);
				hslCities[i].MarkBrush?.Dispose();
				hslCities[i].MarkBrush = new SolidBrush(Color.Tomato);
			}
			Invalidate();
		}

		public void DrawLineAndImage(Graphics g, Point start, Point finish, float percent, Bitmap image, bool noScale = true)
		{
			double num = Math.Sqrt((finish.X - start.X) * (finish.X - start.X) + (finish.Y - start.Y) * (finish.Y - start.Y));
			if (dashPen == null)
			{
				dashPen = new Pen(Color.Gray, 1f / GetScales());
				dashPen.DashStyle = DashStyle.Custom;
				dashPen.DashPattern = new float[2] { 8f, 8f };
			}
			else if (Math.Abs(dashPen.Width - 1f / GetScales()) > 0.1f)
			{
				dashPen?.Dispose();
				dashPen = new Pen(Color.Gray, 1f / GetScales());
				dashPen.DashStyle = DashStyle.Custom;
				dashPen.DashPattern = new float[2] { 8f, 8f };
			}
			g.DrawLine(dashPen, start, finish);
			double num2 = Math.Atan2(finish.Y - start.Y, finish.X - start.X);
			g.TranslateTransform(start.X, start.Y);
			float num3 = (float)(num2 * 180.0 / Math.PI + 90.0);
			g.RotateTransform(num3);
			if (image != null)
			{
				if (noScale)
				{
					int num4 = Convert.ToInt32((float)image.Width / GetScales());
					g.DrawImage(image, new RectangleF(height: Convert.ToInt32((float)image.Height / GetScales()), x: -num4 / 2, y: -Convert.ToInt32(num * (double)percent / 100.0), width: num4));
				}
				else
				{
					g.DrawImage(image, new RectangleF(image.Width / 2, -Convert.ToInt32(num * (double)percent / 100.0), image.Width, image.Height));
				}
			}
			g.RotateTransform(0f - num3);
			g.TranslateTransform(-start.X, -start.Y);
		}

		public void DrawLineAndImage(Graphics g, string startCity, string finishCity, float percent, Bitmap image, bool noScale = true)
		{
			DrawLineAndImage(g, hslCities.Find((HslCity m) => m.Name.Contains(startCity)).Location, hslCities.Find((HslCity m) => m.Name.Contains(finishCity)).Location, percent, image, noScale);
		}

		private void InitializeComponent()
		{
			base.SuspendLayout();
			this.Font = new System.Drawing.Font("微软雅黑", 9f, System.Drawing.FontStyle.Regular, System.Drawing.GraphicsUnit.Point, 134);
			base.Name = "HslChinaMap";
			base.ResumeLayout(false);
		}
	}
